15: /// A `Revwalk` with an associated "hide callback", see `with_hide_callback`
16: pub struct RevwalkWithHideCb<'repo, 'cb, C>
17: where
18:     C: FnMut(Oid) -> bool,
19: {
20:     revwalk: Revwalk<'repo>,
21:     _marker: marker::PhantomData<&'cb C>,
22: }
23: 
24: extern "C" fn revwalk_hide_cb<C>(commit_id: *const raw::git_oid, payload: *mut c_void) -> c_int
25: where
26:     C: FnMut(Oid) -> bool,
27: {
28:     panic::wrap(|| unsafe {
29:         let hide_cb = payload as *mut C;
30:         if (*hide_cb)(Oid::from_raw(commit_id)) {
31:             1
32:         } else {
33:             0
34:         }
35:     })
36:     .unwrap_or(-1)
37: }
