70:     panic::wrap(|| unsafe {
71:         let hunk = Binding::from_raw_opt(hunk);
72: 
73:         let payload = &mut *(data as *mut ApplyOptions<'_>);
74:         let callback = match payload.hunk_cb {
75:             Some(ref mut c) => c,
76:             None => return -1,
77:         };
78: 
79:         let apply = callback(hunk);
80:         if apply {
81:             0
82:         } else {
83:             1
84:         }
